#include <string>
#include <vector>
#include <unordered_set>

class Solution {
public:
    int numSplits(std::string s) {
        int n = s.size();
        std::vector<int> pref(n), suff(n);
        std::unordered_set<char> seen;
        for (int i = 0; i < n; ++i) {
            seen.insert(s[i]);
            pref[i] = seen.size();
        }
        seen.clear();
        for (int i = n - 1; i >= 0; --i) {
            seen.insert(s[i]);
            suff[i] = seen.size();
        }
        int ans = 0;
        for (int i = 0; i < n - 1; ++i) {
            if (pref[i] == suff[i + 1]) ans++;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int numSplits(String s) {
        int n = s.length();
        int[] pref = new int[n];
        int[] suff = new int[n];
        Set<Character> seen = new HashSet<>();
        for (int i = 0; i < n; i++) {
            seen.add(s.charAt(i));
            pref[i] = seen.size();
        }
        seen.clear();
        for (int i = n - 1; i >= 0; i--) {
            seen.add(s.charAt(i));
            suff[i] = seen.size();
        }
        int ans = 0;
        for (int i = 0; i < n - 1; i++) {
            if (pref[i] == suff[i + 1]) ans++;
        }
        return ans;
    }
}

